-- Insert payment records with calculated totals

-- Summary of payments
SELECT 
    'PAYMENT SUMMARY' as summary,
    COUNT(*) as total_students,
    SUM(amount) / 100 as total_amount_kes,
    AVG(amount) / 100 as average_payment_kes
FROM payments 
WHERE notes LIKE '%handwritten records%';